mapper.delete:
DELETE
FROM t_pe_prompt
WHERE task_id = #{taskId} and workspace_id = #{workspaceId}
  and type = 0
  and id NOT IN (SELECT id
                 FROM (SELECT id
                       FROM t_pe_prompt
                       WHERE task_id = #{taskId}
                         and type = 0
                       ORDER BY created_on DESC LIMIT 99) AS latest_data);

mapper.select:
select *
from t_pe_prompt
where id = #{promptId} AND workspace_id = #{workspaceId}

select *
from t_pe_prompt
where task_id = #{body.taskId} AND workspace_id = #{workspaceId}


    and question like #{contentKeyWordPattern}



    and name like #{nameKeyWordPattern}


    and type = #{body.type}


    order by manual_score desc


    order by created_on desc

SELECT * FROM t_pe_prompt WHERE workspace_id = #{workspaceId}
AND id IN
#{id}
ORDER BY updated_on DESC

SELECT 1
FROM t_pe_prompt
WHERE name = #{name}
AND task_id = #{taskId} AND workspace_id = #{workspaceId}

    AND id != #{id}

LIMIT 1

SELECT COUNT(1)
FROM t_pe_prompt
WHERE name = #{name}
  AND workspace_id = #{workspaceId}
  AND task_id = (
    SELECT task_id
    FROM t_pe_prompt
    WHERE id = #{id}
      AND workspace_id = #{workspaceId}
)
